function strongPasswordEdits(password: string): number {
  const s = password, n = s.length;
  const missing = 3 - (/[a-z]/.test(s) ? 1 : 0) - (/[A-Z]/.test(s) ? 1 : 0) - (/[0-9]/.test(s) ? 1 : 0);
  if (n < 6) return Math.max(missing, 6 - n);
  let replace = 0, one = 0, two = 0;
  for (let i = 0; i < n; ) {
    let j = i;
    while (j < n && s[j] === s[i]) j++;
    const L = j - i;
    if (L >= 3) {
      replace += Math.floor(L / 3);
      if (L % 3 === 0) one++;
      else if (L % 3 === 1) two++;
    }
    i = j;
  }
  if (n <= 20) return Math.max(missing, replace);
  const del = n - 20;
  replace -= Math.min(del, one);
  replace -= Math.floor(Math.min(Math.max(del - one, 0), 2 * two) / 2);
  replace -= Math.floor(Math.max(del - one - 2 * two, 0) / 3);
  return del + Math.max(missing, replace);
}

